const u=new Intl.NumberFormat("fa-IR");function t(n){return u.format(n)}function m(n){return`${t(n)} تومان`}function c(){return new Intl.DateTimeFormat("fa-IR-u-ca-persian",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(new Date)}function f(n){return new Intl.DateTimeFormat("fa-IR-u-ca-persian",{day:"numeric",month:"long",year:"numeric"}).format(new Date(n))}function s(n){return n?new Intl.DateTimeFormat("fa-IR-u-ca-persian",{day:"numeric",month:"long",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(new Date(n)):"زمان انتشار نامشخص"}function d(n,i){if(!n)return"زمان نامشخص";const a=Math.max(0,Math.round((i-n)/1e3));if(a<60)return"همین حالا";const r=Math.floor(a/60);if(r<60)return`${t(r)} دقیقه پیش`;const e=Math.floor(r/60);if(e<24)return`${t(e)} ساعت پیش`;const o=Math.floor(e/24);return o<7?`${t(o)} روز پیش`:f(n)}export{c as a,d as b,m as c,s as d,f as e,t as f};
